extends CharacterBody2D

var hp = 0

@onready var detector_shape = $detector/CollisionShape2D
@onready var anim = $AnimatedSprite2D
@onready var animP = $AnimationPlayer
@onready var attack_timer = $attack_timer
# --- НОВОЕ ---
@onready var hp_bar = $TextureProgressBar

var speed = GameConstants.ENEMY_GOBLIN_AXE_MAX_SPEED
enum Dir { DOWN, UP, LEFT, RIGHT }
var current_dir = Dir.DOWN

var player: Node2D = null
var parent_node: Node = null
var room_node: Node2D = null

var can_walk = true
var can_attack = true
var can_anim = true 
var player_in_range = false
var smite_instance: Node2D = null
var is_dead = false 

func _ready() -> void:
	# Применяем масштабирование по уровню врагов
	hp = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_HP)
	speed = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_MAX_SPEED)

	# --- НОВОЕ ---
	# Инициализируем полоску здоровья при появлении врага
	hp_bar.update_hp(hp, hp)

	player = get_tree().get_first_node_in_group("player") as Node2D
	parent_node = get_parent()
	if parent_node:
		room_node = parent_node.get_parent()

func _physics_process(_delta: float) -> void:
	if is_dead: return 

	if not can_walk:
		velocity = Vector2.ZERO
		move_and_slide()
		return

	var is_aggressive = parent_node and parent_node.get("aggression")

	if is_instance_valid(player) and is_aggressive:
		var to_player = player.global_position - global_position
		var direction = to_player.normalized()

		velocity = direction * speed
		move_and_slide()

		if can_anim:
			update_run_animation(direction)
	else:
		velocity = Vector2.ZERO
		move_and_slide()
		if can_anim:
			play_idle_animation()

func update_run_animation(direction: Vector2):
	if abs(direction.x) > abs(direction.y):
		if direction.x > 0:
			anim.play("run_right")
			current_dir = Dir.RIGHT
		else:
			anim.play("run_left")
			current_dir = Dir.LEFT
	else:
		if direction.y > 0:
			anim.play("run_down")
			current_dir = Dir.DOWN
		else:
			anim.play("run_up")
			current_dir = Dir.UP

func _process(_delta):
	if hp <= 0 and not is_dead:
		death()

func attack():
	if not can_attack or not player_in_range or is_dead:
		return

	can_attack = false
	can_anim = false
	anim.stop()
	speed *= 1.5
	match current_dir:
		Dir.UP: animP.play("attack_up")
		Dir.DOWN: animP.play("attack_down")
		Dir.LEFT: animP.play("attack_left")
		Dir.RIGHT: animP.play("attack_right")

	await animP.animation_finished
	speed /= 1.5
	can_anim = true
	if is_instance_valid(smite_instance):
		smite_instance.queue_free()
		smite_instance = null

	if not is_dead and can_anim:
		attack_timer.start()

func play_idle_animation():
	if is_dead: return
	var target_idle = "idle_down"
	if anim.animation != target_idle:
		anim.play(target_idle)

func take_damage(amount: int):
	if is_dead: return

	hp -= amount
	# --- НОВОЕ ---
	# Обновляем полоску здоровья каждый раз, когда враг получает урон
	var max_hp = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_HP)
	hp_bar.update_hp(hp, max_hp)

	can_walk = false
	can_anim = false 
	animP.stop()    

	if hp <= 0:
		death()
		return

	match current_dir:
		Dir.UP: anim.play("hurt_up")
		Dir.DOWN: anim.play("hurt_down")
		Dir.LEFT: anim.play("hurt_left")
		Dir.RIGHT: anim.play("hurt_right")

	await anim.animation_finished

	if not is_dead:
		can_anim = true
		can_walk = true
		can_attack = true

func death():
	if is_dead: return
	is_dead = true
	can_walk = false
	can_attack = false
	velocity = Vector2.ZERO

	anim.stop()
	animP.stop()

	set_collision_layer_value(1, false)
	set_collision_mask_value(1, false)

	match current_dir:
		Dir.UP: anim.play("death_up")
		Dir.DOWN: anim.play("death_down")
		Dir.LEFT: anim.play("death_left")
		Dir.RIGHT: anim.play("death_right")

	await anim.animation_finished

	# Выдаем опыт игроку
	_give_exp_to_player()

	if randf() <= 0.25:
		_spawn_loot()

	queue_free()

func _give_exp_to_player():
	var player_node = get_tree().get_first_node_in_group("player")
	if player_node and player_node.has_method("add_experience"):
		var exp_reward = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_EXP_REWARD)
		print("Goblin Axe выдает опыт: ", exp_reward, " (уровень врагов: ", GameConstants.ENEMY_LEVEL, ")")
		player_node.add_experience(exp_reward)
	else:
		print("ОШИБКА: Игрок не найден или нет метода add_experience")

func _spawn_loot():
	var potion = GameConstants.HEALTH_POTION.instantiate()
	potion.global_position = global_position
	# Добавляем в комнату, а не в Enemys node, чтобы не блокировать двери
	if parent_node:
		room_node.add_child(potion)
	else:
		get_parent().add_child(potion)

func swing():
	if not is_instance_valid(player) or is_dead: return
	smite_instance = GameConstants.ENEMY_GOBLIN_AXE_SMITE.instantiate()
	add_child(smite_instance)
	smite_instance.visible = false
	smite_instance.monitoring = false

	var target_dir = (player.global_position - global_position).normalized()
	if "direction" in smite_instance:
		smite_instance.direction = target_dir

	smite_instance.position = target_dir * GameConstants.ENEMY_GOBLIN_AXE_SMITE_OFFSET 
	smite_instance.rotation = target_dir.angle()

func activate_smite():
	if is_instance_valid(smite_instance) and not is_dead:
		smite_instance.visible = true
		smite_instance.monitoring = true

func _on_detector_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player"):
		player_in_range = true
		if can_attack:
			attack()

func _on_detector_body_exited(body: Node2D) -> void:
	if body.is_in_group("player"):
		player_in_range = false

func _on_attack_timer_timeout():
	if is_dead: return
	can_attack = true
	var is_aggressive = parent_node and parent_node.get("aggression")
	if player_in_range and is_aggressive:
		attack()

func _on_hitbox_area_entered(_area: Area2D) -> void:
	take_damage(GameConstants.ENEMY_GOBLIN_AXE_TAKE_DAMAGE)

func _on_hitbox_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player") and body.has_method("take_damage"):
		var damage = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_DAMAGE)
		body.take_damage(damage)

extends CharacterBody2D

# Настройки из глобальных констант
@export var hp = 0
var max_speed = 0.0
var damage = 15

@onready var animP = $AnimationPlayer
@onready var attack_timer = $attack_timer
@onready var anim = $AnimatedSprite2D
@onready var hp_bar = $TextureProgressBar

# Ссылки на окружение
var player: Node2D = null
var parent_node: Node = null
var room_node: Node2D = null

# Направления
enum Dir { DOWN, UP, LEFT, RIGHT }
var current_dir = Dir.DOWN

# Флаги состояний
var can_move = true
var can_attack = false
var player_in_range = false
var get_closer = true
var is_dead = false
var can_anim = true

func _ready() -> void:
	# Инициализация параметров с масштабированием
	hp = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_HP)
	max_speed = randf_range(
		GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_SPEED_MIN),
		GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_SPEED_MAX)
	)

	hp_bar.update_hp(hp, hp)

	player = get_tree().get_first_node_in_group("player") as Node2D
	parent_node = get_parent()

	if parent_node:
		room_node = parent_node.get_parent()

	attack_timer.start(1.0)

func _physics_process(_delta: float) -> void:
	if is_dead: return

	var is_aggressive = parent_node and parent_node.get("aggression")

	if is_aggressive and player_in_range and can_attack and can_move:
		attack()

	if not player or not is_instance_valid(player) or not can_move:
		velocity = Vector2.ZERO
		if not animP.is_playing() and can_anim:
			play_idle_animation()
		move_and_slide()
		return

	var to_player: Vector2 = player.global_position - global_position
	var direction = to_player.normalized()

	update_direction(direction)

	if is_aggressive and get_closer:
		velocity = direction * max_speed
		if can_anim:
			play_run_animation()
		move_and_slide()
	else:
		velocity = Vector2.ZERO
		if can_anim:
			play_idle_animation()

func _process(_delta):
	if hp <= 0 and not is_dead:
		death()

func update_direction(dir: Vector2):
	if abs(dir.x) > abs(dir.y):
		current_dir = Dir.LEFT if dir.x < 0 else Dir.RIGHT
	else:
		current_dir = Dir.UP if dir.y < 0 else Dir.DOWN

func play_run_animation():
	match current_dir:
		Dir.UP: anim.play("run_up")
		Dir.DOWN: anim.play("run_down")
		Dir.LEFT: anim.play("run_left")
		Dir.RIGHT: anim.play("run_right")

func play_idle_animation():
	if is_dead: return
	if anim.animation != "idle_down":
		anim.play("idle_down")

func attack():
	if not can_attack or not player_in_range or is_dead:
		return

	can_move = false
	can_attack = false

	match current_dir:
		Dir.UP: animP.play("attack_up")
		Dir.DOWN: animP.play("attack_down")
		Dir.LEFT: animP.play("attack_left")
		Dir.RIGHT: animP.play("attack_right")

	await animP.animation_finished

	if not is_dead:
		can_move = true
		attack_timer.start()

func take_damage(amount: int):
	if is_dead: return

	hp -= amount
	var max_hp = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_HP)
	hp_bar.update_hp(hp, max_hp)

	can_anim = false
	can_move = false
	animP.stop()

	if hp <= 0:
		death()
		return

	match current_dir:
		Dir.UP: anim.play("hurt_up")
		Dir.DOWN: anim.play("hurt_down")
		Dir.LEFT: anim.play("hurt_left")
		Dir.RIGHT: anim.play("hurt_right")

	await anim.animation_finished

	if not is_dead:
		can_anim = true
		can_move = true

		if attack_timer.is_stopped():
			attack_timer.start(1.0)

func shoot_poison():
	if not player or not is_instance_valid(player) or is_dead: return

	var projectile_instance = GameConstants.GOBLIN_SLINGER_PROJECTILE.instantiate()
	projectile_instance.global_position = global_position

	var target_dir = (player.global_position - global_position).normalized()
	projectile_instance.direction = target_dir
	projectile_instance.rotation = target_dir.angle()

	get_tree().current_scene.add_child.call_deferred(projectile_instance)
	print("Goblin Slinger выстрелил ядовитым снарядом!")

func death():
	if is_dead: return
	is_dead = true
	can_move = false
	can_attack = false
	velocity = Vector2.ZERO

	anim.stop()
	animP.stop()

	set_collision_layer_value(1, false)
	set_collision_mask_value(1, false)

	match current_dir:
		Dir.UP: anim.play("death_up")
		Dir.DOWN: anim.play("death_down")
		Dir.LEFT: anim.play("death_left")
		Dir.RIGHT: anim.play("death_right")

	await anim.animation_finished

	_give_exp_to_player()

	if randf() <= 0.25:
		_spawn_loot()

	queue_free()

func _give_exp_to_player():
	var player_node = get_tree().get_first_node_in_group("player")
	if player_node and player_node.has_method("add_experience"):
		var exp_reward = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_EXP_REWARD)
		print("Goblin Slinger выдает опыт: ", exp_reward, " (уровень врагов: ", GameConstants.ENEMY_LEVEL, ")")
		player_node.add_experience(exp_reward)
	else:
		print("ОШИБКА: Игрок не найден или нет метода add_experience")

func _spawn_loot():
	var potion = GameConstants.HEALTH_POTION.instantiate()
	potion.global_position = global_position
	if parent_node:
		room_node.add_child(potion)
	else:
		get_parent().add_child(potion)

func _on_detector_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player"):
		player_in_range = true
		get_closer = false

		if can_attack:
			can_attack = false
			attack_timer.start(1.0)

func _on_detector_body_exited(body: Node2D) -> void:
	if body.is_in_group("player"):
		player_in_range = false
		get_closer = true

func _on_attack_timer_timeout():
	if is_dead: return
	can_attack = true

func _on_hitbox_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player") and body.has_method("take_damage"):
		var damage = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_BODY_DAMAGE)
		body.take_damage(damage)

extends Control

# Настройки сетки
@export var grid_columns: int = 8  # Количество колонок как в Isaac
@export var icon_size: int = 32  # Размер иконки
@export var icon_spacing: int = 4  # Отступ между иконками

# Контейнер для иконок
@onready var grid_container: GridContainer

var collected_artefacts: Array = []

func _ready():
	add_to_group("backpack")
	setup_grid()

	# Восстанавливаем артефакты из сохранения
	if SaveSystem.has_collected_artefacts():
		var saved_artefacts = SaveSystem.get_collected_artefacts()
		for artefact_data in saved_artefacts:
			# Загружаем иконку из пути
			var icon_texture = null
			if artefact_data.get("icon_path", "") != "":
				icon_texture = load(artefact_data["icon_path"])

			var artefact_info = {
				"name": artefact_data.get("name", "Unknown"),
				"icon": icon_texture,
				"description": artefact_data.get("description", "")
			}
			collected_artefacts.append(artefact_info)
			create_icon(artefact_info)
		print("Восстановлено артефактов: ", saved_artefacts.size())

func setup_grid():
	# Создаем GridContainer если его нет
	if not grid_container:
		grid_container = GridContainer.new()
		add_child(grid_container)

	# Настраиваем сетку
	grid_container.columns = grid_columns
	grid_container.add_theme_constant_override("h_separation", icon_spacing)
	grid_container.add_theme_constant_override("v_separation", icon_spacing)

	# Позиционируем в правом верхнем углу
	grid_container.position = Vector2(10, 10)

func add_artefact(artefact_data) -> void:
	# Сохраняем данные артефакта
	var artefact_info = {
		"name": artefact_data.artefact_name if "artefact_name" in artefact_data else "Unknown",
		"icon": artefact_data.artefact_icon if "artefact_icon" in artefact_data else null,
		"icon_path": artefact_data.artefact_icon.resource_path if (artefact_data.artefact_icon and "artefact_icon" in artefact_data) else "",
		"description": artefact_data.artefact_description if "artefact_description" in artefact_data else ""
	}

	collected_artefacts.append(artefact_info)

	# Создаем иконку
	create_icon(artefact_info)

	print("Артефакт добавлен в рюкзак: ", artefact_info["name"])

func create_icon(artefact_info: Dictionary) -> void:
	# Создаем контейнер для иконки
	var icon_panel = PanelContainer.new()
	icon_panel.custom_minimum_size = Vector2(icon_size, icon_size)

	# Стилизация панели (темный фон с рамкой)
	var style_box = StyleBoxFlat.new()
	style_box.bg_color = Color(0.1, 0.1, 0.1, 0.8)
	style_box.border_color = Color(0.3, 0.3, 0.3, 1.0)
	style_box.border_width_left = 1
	style_box.border_width_right = 1
	style_box.border_width_top = 1
	style_box.border_width_bottom = 1
	icon_panel.add_theme_stylebox_override("panel", style_box)

	# Создаем TextureRect для иконки
	var texture_rect = TextureRect.new()
	texture_rect.expand_mode = TextureRect.EXPAND_FIT_WIDTH_PROPORTIONAL
	texture_rect.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
	texture_rect.custom_minimum_size = Vector2(icon_size - 4, icon_size - 4)

	if artefact_info["icon"]:
		texture_rect.texture = artefact_info["icon"]
	else:
		# Если нет иконки, показываем заглушку
		texture_rect.modulate = Color(0.5, 0.5, 0.5, 1.0)

	icon_panel.add_child(texture_rect)

	# Добавляем tooltip с описанием
	icon_panel.tooltip_text = artefact_info["name"] + "\n" + artefact_info["description"]

	# Добавляем в сетку
	grid_container.add_child(icon_panel)

	# Анимация появления
	animate_icon_appear(icon_panel)

func animate_icon_appear(icon: Control) -> void:
	# Начинаем с маленького размера
	icon.scale = Vector2(0.1, 0.1)
	icon.modulate.a = 0.0

	# Анимация увеличения и появления
	var tween = create_tween()
	tween.set_parallel(true)
	tween.set_ease(Tween.EASE_OUT)
	tween.set_trans(Tween.TRANS_BACK)

	tween.tween_property(icon, "scale", Vector2(1.0, 1.0), 0.3)
	tween.tween_property(icon, "modulate:a", 1.0, 0.3)

func get_artefact_count() -> int:
	return collected_artefacts.size()

func has_artefact(artefact_name: String) -> bool:
	for artefact in collected_artefacts:
		if artefact["name"] == artefact_name:
			return true
	return false

func clear_backpack() -> void:
	collected_artefacts.clear()
	for child in grid_container.get_children():
		child.queue_free()

func get_collected_artefact_names() -> Array:
	var artefacts_data = []
	for artefact in collected_artefacts:
		artefacts_data.append({
			"name": artefact["name"],
			"icon_path": artefact.get("icon_path", ""),
			"description": artefact.get("description", "")
		})
	return artefacts_data

