extends CharacterBody2D

var hp = 0

@onready var detector_shape = $detector/CollisionShape2D
@onready var anim = $AnimatedSprite2D
@onready var animP = $AnimationPlayer
@onready var attack_timer = $attack_timer
# --- НОВОЕ ---
@onready var hp_bar = $TextureProgressBar

var speed = GameConstants.ENEMY_GOBLIN_AXE_MAX_SPEED
enum Dir { DOWN, UP, LEFT, RIGHT }
var current_dir = Dir.DOWN

var player: Node2D = null
var parent_node: Node = null
var room_node: Node2D = null

var can_walk = true
var can_attack = true
var can_anim = true 
var player_in_range = false
var smite_instance: Node2D = null
var is_dead = false 

func _ready() -> void:
	# Применяем масштабирование по уровню врагов
	hp = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_HP)
	speed = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_MAX_SPEED)

	# --- НОВОЕ ---
	# Инициализируем полоску здоровья при появлении врага
	hp_bar.update_hp(hp, hp)

	player = get_tree().get_first_node_in_group("player") as Node2D
	parent_node = get_parent()
	if parent_node:
		room_node = parent_node.get_parent()

func _physics_process(_delta: float) -> void:
	if is_dead: return 

	if not can_walk:
		velocity = Vector2.ZERO
		move_and_slide()
		return

	var is_aggressive = parent_node and parent_node.get("aggression")

	if is_instance_valid(player) and is_aggressive:
		var to_player = player.global_position - global_position
		var direction = to_player.normalized()

		velocity = direction * speed
		move_and_slide()

		if can_anim:
			update_run_animation(direction)
	else:
		velocity = Vector2.ZERO
		move_and_slide()
		if can_anim:
			play_idle_animation()

func update_run_animation(direction: Vector2):
	if abs(direction.x) > abs(direction.y):
		if direction.x > 0:
			anim.play("run_right")
			current_dir = Dir.RIGHT
		else:
			anim.play("run_left")
			current_dir = Dir.LEFT
	else:
		if direction.y > 0:
			anim.play("run_down")
			current_dir = Dir.DOWN
		else:
			anim.play("run_up")
			current_dir = Dir.UP

func _process(_delta):
	if hp <= 0 and not is_dead:
		death()

func attack():
	if not can_attack or not player_in_range or is_dead:
		return

	can_attack = false
	can_anim = false
	anim.stop()
	speed *= 1.5
	match current_dir:
		Dir.UP: animP.play("attack_up")
		Dir.DOWN: animP.play("attack_down")
		Dir.LEFT: animP.play("attack_left")
		Dir.RIGHT: animP.play("attack_right")

	await animP.animation_finished
	speed /= 1.5
	can_anim = true
	if is_instance_valid(smite_instance):
		smite_instance.queue_free()
		smite_instance = null

	if not is_dead and can_anim:
		attack_timer.start()

func play_idle_animation():
	if is_dead: return
	var target_idle = "idle_down"
	if anim.animation != target_idle:
		anim.play(target_idle)

func take_damage(amount: int):
	if is_dead: return

	hp -= amount
	# --- НОВОЕ ---
	# Обновляем полоску здоровья каждый раз, когда враг получает урон
	var max_hp = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_HP)
	hp_bar.update_hp(hp, max_hp)

	can_walk = false
	can_anim = false 
	animP.stop()    

	if hp <= 0:
		death()
		return

	match current_dir:
		Dir.UP: anim.play("hurt_up")
		Dir.DOWN: anim.play("hurt_down")
		Dir.LEFT: anim.play("hurt_left")
		Dir.RIGHT: anim.play("hurt_right")

	await anim.animation_finished

	if not is_dead:
		can_anim = true
		can_walk = true
		can_attack = true

func death():
	if is_dead: return
	is_dead = true
	can_walk = false
	can_attack = false
	velocity = Vector2.ZERO

	anim.stop()
	animP.stop()

	set_collision_layer_value(1, false)
	set_collision_mask_value(1, false)

	match current_dir:
		Dir.UP: anim.play("death_up")
		Dir.DOWN: anim.play("death_down")
		Dir.LEFT: anim.play("death_left")
		Dir.RIGHT: anim.play("death_right")

	await anim.animation_finished

	# Выдаем опыт игроку
	_give_exp_to_player()

	if randf() <= 0.25:
		_spawn_loot()

	queue_free()

func _give_exp_to_player():
	var player_node = get_tree().get_first_node_in_group("player")
	if player_node and player_node.has_method("add_experience"):
		var exp_reward = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_EXP_REWARD)
		print("Goblin Axe выдает опыт: ", exp_reward, " (уровень врагов: ", GameConstants.ENEMY_LEVEL, ")")
		player_node.add_experience(exp_reward)
	else:
		print("ОШИБКА: Игрок не найден или нет метода add_experience")

func _spawn_loot():
	var potion = GameConstants.HEALTH_POTION.instantiate()
	potion.global_position = global_position
	# Добавляем в комнату, а не в Enemys node, чтобы не блокировать двери
	if parent_node:
		room_node.add_child(potion)
	else:
		get_parent().add_child(potion)

func swing():
	if not is_instance_valid(player) or is_dead: return
	smite_instance = GameConstants.ENEMY_GOBLIN_AXE_SMITE.instantiate()
	add_child(smite_instance)
	smite_instance.visible = false
	smite_instance.monitoring = false

	var target_dir = (player.global_position - global_position).normalized()
	if "direction" in smite_instance:
		smite_instance.direction = target_dir

	smite_instance.position = target_dir * GameConstants.ENEMY_GOBLIN_AXE_SMITE_OFFSET 
	smite_instance.rotation = target_dir.angle()

func activate_smite():
	if is_instance_valid(smite_instance) and not is_dead:
		smite_instance.visible = true
		smite_instance.monitoring = true

func _on_detector_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player"):
		player_in_range = true
		if can_attack:
			attack()

func _on_detector_body_exited(body: Node2D) -> void:
	if body.is_in_group("player"):
		player_in_range = false

func _on_attack_timer_timeout():
	if is_dead: return
	can_attack = true
	var is_aggressive = parent_node and parent_node.get("aggression")
	if player_in_range and is_aggressive:
		attack()

func _on_hitbox_area_entered(_area: Area2D) -> void:
	take_damage(GameConstants.ENEMY_GOBLIN_AXE_TAKE_DAMAGE)

func _on_hitbox_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player") and body.has_method("take_damage"):
		var damage = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_GOBLIN_AXE_DAMAGE)
		body.take_damage(damage)

extends CharacterBody2D

# Настройки из глобальных констант
@export var hp = 0
var max_speed = 0.0
var damage = 15

@onready var animP = $AnimationPlayer
@onready var attack_timer = $attack_timer
@onready var anim = $AnimatedSprite2D
@onready var hp_bar = $TextureProgressBar

# Ссылки на окружение
var player: Node2D = null
var parent_node: Node = null
var room_node: Node2D = null

# Направления
enum Dir { DOWN, UP, LEFT, RIGHT }
var current_dir = Dir.DOWN

# Флаги состояний
var can_move = true
var can_attack = false
var player_in_range = false
var get_closer = true
var is_dead = false
var can_anim = true

func _ready() -> void:
	# Инициализация параметров с масштабированием
	hp = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_HP)
	max_speed = randf_range(
		GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_SPEED_MIN),
		GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_SPEED_MAX)
	)

	hp_bar.update_hp(hp, hp)

	player = get_tree().get_first_node_in_group("player") as Node2D
	parent_node = get_parent()

	if parent_node:
		room_node = parent_node.get_parent()

	attack_timer.start(1.0)

func _physics_process(_delta: float) -> void:
	if is_dead: return

	var is_aggressive = parent_node and parent_node.get("aggression")

	if is_aggressive and player_in_range and can_attack and can_move:
		attack()

	if not player or not is_instance_valid(player) or not can_move:
		velocity = Vector2.ZERO
		if not animP.is_playing() and can_anim:
			play_idle_animation()
		move_and_slide()
		return

	var to_player: Vector2 = player.global_position - global_position
	var direction = to_player.normalized()

	update_direction(direction)

	if is_aggressive and get_closer:
		velocity = direction * max_speed
		if can_anim:
			play_run_animation()
		move_and_slide()
	else:
		velocity = Vector2.ZERO
		if can_anim:
			play_idle_animation()

func _process(_delta):
	if hp <= 0 and not is_dead:
		death()

func update_direction(dir: Vector2):
	if abs(dir.x) > abs(dir.y):
		current_dir = Dir.LEFT if dir.x < 0 else Dir.RIGHT
	else:
		current_dir = Dir.UP if dir.y < 0 else Dir.DOWN

func play_run_animation():
	match current_dir:
		Dir.UP: anim.play("run_up")
		Dir.DOWN: anim.play("run_down")
		Dir.LEFT: anim.play("run_left")
		Dir.RIGHT: anim.play("run_right")

func play_idle_animation():
	if is_dead: return
	if anim.animation != "idle_down":
		anim.play("idle_down")

func attack():
	if not can_attack or not player_in_range or is_dead:
		return

	can_move = false
	can_attack = false

	match current_dir:
		Dir.UP: animP.play("attack_up")
		Dir.DOWN: animP.play("attack_down")
		Dir.LEFT: animP.play("attack_left")
		Dir.RIGHT: animP.play("attack_right")

	await animP.animation_finished

	if not is_dead:
		can_move = true
		attack_timer.start()

func take_damage(amount: int):
	if is_dead: return

	hp -= amount
	var max_hp = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_HP)
	hp_bar.update_hp(hp, max_hp)

	can_anim = false
	can_move = false
	animP.stop()

	if hp <= 0:
		death()
		return

	match current_dir:
		Dir.UP: anim.play("hurt_up")
		Dir.DOWN: anim.play("hurt_down")
		Dir.LEFT: anim.play("hurt_left")
		Dir.RIGHT: anim.play("hurt_right")

	await anim.animation_finished

	if not is_dead:
		can_anim = true
		can_move = true

		if attack_timer.is_stopped():
			attack_timer.start(1.0)

func shoot_poison():
	if not player or not is_instance_valid(player) or is_dead: return

	var projectile_instance = GameConstants.GOBLIN_SLINGER_PROJECTILE.instantiate()
	projectile_instance.global_position = global_position

	var target_dir = (player.global_position - global_position).normalized()
	projectile_instance.direction = target_dir
	projectile_instance.rotation = target_dir.angle()

	get_tree().current_scene.add_child.call_deferred(projectile_instance)
	print("Goblin Slinger выстрелил ядовитым снарядом!")

func death():
	if is_dead: return
	is_dead = true
	can_move = false
	can_attack = false
	velocity = Vector2.ZERO

	anim.stop()
	animP.stop()

	set_collision_layer_value(1, false)
	set_collision_mask_value(1, false)

	match current_dir:
		Dir.UP: anim.play("death_up")
		Dir.DOWN: anim.play("death_down")
		Dir.LEFT: anim.play("death_left")
		Dir.RIGHT: anim.play("death_right")

	await anim.animation_finished

	_give_exp_to_player()

	if randf() <= 0.25:
		_spawn_loot()

	queue_free()

func _give_exp_to_player():
	var player_node = get_tree().get_first_node_in_group("player")
	if player_node and player_node.has_method("add_experience"):
		var exp_reward = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_EXP_REWARD)
		print("Goblin Slinger выдает опыт: ", exp_reward, " (уровень врагов: ", GameConstants.ENEMY_LEVEL, ")")
		player_node.add_experience(exp_reward)
	else:
		print("ОШИБКА: Игрок не найден или нет метода add_experience")

func _spawn_loot():
	var potion = GameConstants.HEALTH_POTION.instantiate()
	potion.global_position = global_position
	if parent_node:
		room_node.add_child(potion)
	else:
		get_parent().add_child(potion)

func _on_detector_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player"):
		player_in_range = true
		get_closer = false

		if can_attack:
			can_attack = false
			attack_timer.start(1.0)

func _on_detector_body_exited(body: Node2D) -> void:
	if body.is_in_group("player"):
		player_in_range = false
		get_closer = true

func _on_attack_timer_timeout():
	if is_dead: return
	can_attack = true

func _on_hitbox_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player") and body.has_method("take_damage"):
		var damage = GameConstants.get_scaled_enemy_stat(GameConstants.GOBLIN_SLINGER_BODY_DAMAGE)
		body.take_damage(damage)

extends CharacterBody2D

const HATCH_SCENE = preload("res://scene/pick_up/hatch.tscn")

var hp = 0
var speed = GameConstants.ENEMY_BEASTGOBLIN_MAX_SPEED

@onready var anim = $AnimatedSprite2D
@onready var animP = $AnimationPlayer
@onready var attack_timer = $attack_timer

@onready var hp_bar = $TextureProgressBar

enum Dir { DOWN, UP, LEFT, RIGHT }
var current_dir = Dir.DOWN

var player: Node2D = null
var parent_node: Node = null

# Флаги детекторов
var player_in_bite_zone = false
var player_in_slap_zone = false
var player_in_shoot_zone = false

var can_walk = true
var can_attack = true
var can_anim = true 
var is_dead = false 

var smite_instance: Node2D = null

# Флаг для предотвращения повторных вызовов attack() во время анимации
var is_attacking = false

func _ready() -> void:
	hp = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_BEASTGOBLIN_HP)
	speed = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_BEASTGOBLIN_MAX_SPEED)

	# --- НОВОЕ ---
	hp_bar.update_hp(hp, hp)

	player = get_tree().get_first_node_in_group("player") as Node2D
	parent_node = get_parent()

	attack_timer.one_shot = true
	_play_idle_animation()

func _physics_process(_delta: float) -> void:
	if is_dead: return 

	var is_aggressive = parent_node and parent_node.get("aggression")

	if can_walk and is_instance_valid(player) and is_aggressive:
		var to_player = player.global_position - global_position
		var direction = to_player.normalized()

		# Логика движения: стоим, если игрок в зоне укуса или удара
		if player_in_bite_zone or player_in_slap_zone:
			velocity = Vector2.ZERO
			if can_anim: _play_idle_animation()
		else:
			velocity = direction * speed
			move_and_slide()
			if can_anim: update_run_animation(direction)

		# ПРИОРИТЕТЫ АТАК
		if can_attack and not is_attacking:
			if player_in_bite_zone:
				attack("bite")
			elif player_in_slap_zone:
				attack("slap")
			elif player_in_shoot_zone:
				attack("shoot")
	else:
		velocity = Vector2.ZERO
		move_and_slide()
		if can_anim and not is_dead: _play_idle_animation()

# --- СИСТЕМА АТАК ---

func attack(type: String):
	if not can_attack or is_dead or is_attacking: return

	is_attacking = true
	can_attack = false
	can_walk = false
	can_anim = false

	var anim_name = type + "_" + _get_dir_string()

	if animP.has_animation(anim_name):
		animP.play(anim_name)
		await animP.animation_finished

	# Гарантированно останавливаем AnimationPlayer после анимации
	animP.stop()

	_reset_after_attack()

func _reset_after_attack():
	if is_instance_valid(smite_instance):
		smite_instance.queue_free()
		smite_instance = null

	is_attacking = false

	if not is_dead:
		can_walk = true
		can_anim = true
		# Явно возвращаемся к idle анимации
		_play_idle_animation()
		if attack_timer.is_stopped():
			attack_timer.start()

# --- МЕТОДЫ ДЛЯ АНИМАЦИЙ ---

func spawn_bite_swing():
	if not is_instance_valid(player) or is_dead: return
	smite_instance = GameConstants.ENEMY_GOBLIN_AXE_SMITE.instantiate()
	# Добавляем в сцену, чтобы эффект не "бегал" за гоблином
	get_tree().current_scene.add_child(smite_instance)

	smite_instance.global_position = global_position
	smite_instance.visible = false
	smite_instance.monitoring = false

	var target_dir = (player.global_position - global_position).normalized()
	if "direction" in smite_instance:
		smite_instance.direction = target_dir

	smite_instance.rotation = target_dir.angle()
	smite_instance.global_position += target_dir * 35

func activate_bite():
	if is_instance_valid(smite_instance) and not is_dead:
		smite_instance.visible = true
		smite_instance.monitoring = true

func shoot():
	if is_dead or not is_instance_valid(player): return
	var arrow = GameConstants.SKELETON_BOW_ARROW.instantiate()

	# 1. Сначала определяем направление ОДИН РАЗ
	var dir = (player.global_position - global_position).normalized()

	# 2. Передаем направление в стрелу
	if "direction" in arrow:
		arrow.direction = dir

	# 3. Настраиваем позицию и вращение
	arrow.global_position = global_position
	arrow.rotation = dir.angle()

	# 4. Добавляем в корень сцены (не в гоблина!)
	get_tree().current_scene.add_child(arrow)

# --- УРОН И СИГНАЛЫ ---

func _on_slap_body_entered(body: Node2D) -> void:
	if is_dead: return
	if body.is_in_group("player"):
		if body.has_method("take_damage"):
			var damage = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_BEASTGOBLIN_SLAP_DAMAGE)
			body.take_damage(damage)
		if body.has_method("apply_knockback"):
			body.apply_knockback(global_position, 800.0)

func take_damage(amount: int):
	if is_dead: return
	hp -= amount

	# --- НОВОЕ ---
	var max_hp = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_BEASTGOBLIN_HP)
	hp_bar.update_hp(hp, max_hp)

	# Прерываем анимацию атаки, если гоблина ударили
	animP.stop()
	is_attacking = false

	if hp <= 0:
		death()
		return

	can_anim = false
	can_walk = false
	anim.play("hurt_" + _get_dir_string())
	await anim.animation_finished
	_reset_after_attack()

# --- ПОДКЛЮЧЕНИЕ ДЕТЕКТОРОВ ---

func _on_detector_bite_body_entered(body): if body.is_in_group("player"): player_in_bite_zone = true
func _on_detector_bite_body_exited(body): if body.is_in_group("player"): player_in_bite_zone = false
func _on_detector_slap_body_entered(body): if body.is_in_group("player"): player_in_slap_zone = true
func _on_detector_slap_body_exited(body): if body.is_in_group("player"): player_in_slap_zone = false
func _on_detector_shoot_body_entered(body): if body.is_in_group("player"): player_in_shoot_zone = true
func _on_detector_shoot_body_exited(body): if body.is_in_group("player"): player_in_shoot_zone = false

func _on_hitbox_area_entered(_area): take_damage(GameConstants.ENEMY_BEASTGOBLIN_TAKE_DAMAGE)
func _on_attack_timer_timeout(): can_attack = true

# --- ОБНОВЛЕНИЕ АНИМАЦИЙ ---

func update_run_animation(direction: Vector2):
	if abs(direction.x) > abs(direction.y):
		current_dir = Dir.RIGHT if direction.x > 0 else Dir.LEFT
	else:
		current_dir = Dir.DOWN if direction.y > 0 else Dir.UP
	anim.play("run_" + _get_dir_string())

func _get_dir_string() -> String:
	match current_dir:
		Dir.UP: return "up"
		Dir.DOWN: return "down"
		Dir.LEFT: return "left"
		Dir.RIGHT: return "right"
	return "down"

func _play_idle_animation():
	if anim.animation != "idle_down": anim.play("idle_down")

func death():
	is_dead = true
	can_walk = false
	can_attack = false
	is_attacking = false
	set_collision_layer_value(1, false)
	set_collision_mask_value(1, false)
	animP.stop()
	if is_instance_valid(smite_instance): smite_instance.queue_free()

	var d_anim = "death_" + _get_dir_string()
	if _get_dir_string() == "down": d_anim = "death_dowm"
	anim.play(d_anim)
	await anim.animation_finished

	# Выдаем опыт игроку
	_give_exp_to_player()

	# Спавним лут с большим шансом для босса
	if randf() <= 0.75:
		_spawn_loot()

	# Спавним люк для перехода на следующий этаж
	_spawn_hatch()

	queue_free()

func _spawn_hatch():
	var hatch = HATCH_SCENE.instantiate()
	hatch.global_position = global_position
	get_tree().current_scene.add_child(hatch)
	hatch.open_hatch()

func _give_exp_to_player():
	var player_node = get_tree().get_first_node_in_group("player")
	if player_node and player_node.has_method("add_experience"):
		var exp_reward = GameConstants.get_scaled_enemy_stat(GameConstants.ENEMY_BEASTGOBLIN_EXP_REWARD)
		print("Beast Goblin выдает опыт: ", exp_reward, " (уровень врагов: ", GameConstants.ENEMY_LEVEL, ")")
		player_node.add_experience(exp_reward)
	else:
		print("ОШИБКА: Игрок не найден или нет метода add_experience")

func _spawn_loot():
	var potion = GameConstants.HEALTH_POTION.instantiate()
	potion.global_position = global_position
	# Добавляем в комнату, а не в Enemys node
	if parent_node:
		var room_node = parent_node.get_parent()
		if room_node:
			room_node.add_child(potion)
	else:
		get_parent().add_child(potion)

