extends CharacterBody2D

# Настройки из глобальных констант
@export var hp = 0
var max_speed = 0.0
var damage = 20

@onready var animP = $AnimationPlayer
@onready var attack_timer = $attack_timer
@onready var anim = $AnimatedSprite2D
# --- НОВОЕ ---
@onready var hp_bar = $TextureProgressBar

# Ссылки на окружение
var player: Node2D = null
var parent_node: Node = null
var room_node: Node2D = null

# Направления
enum Dir { DOWN, UP, LEFT, RIGHT }
var current_dir = Dir.DOWN

# Флаги состояний
var can_move = true
var can_attack = false 
var player_in_range = false
var get_closer = true
var is_dead = false 
var can_anim = true 

func _ready() -> void:
	add_to_group("enemys")
	# Инициализация параметров с масштабированием
	hp = GameConstants.get_scaled_enemy_stat(GameConstants.SKELETON_BOW_HP)
	max_speed = randf_range(
		GameConstants.get_scaled_enemy_stat(GameConstants.SKELETON_BOW_SPEED_MIN),
		GameConstants.get_scaled_enemy_stat(GameConstants.SKELETON_BOW_SPEED_MAX)
	)

	# --- НОВОЕ ---
	hp_bar.update_hp(hp, hp)

	player = get_tree().get_first_node_in_group("player") as Node2D
	parent_node = get_parent()

	if parent_node:
		room_node = parent_node.get_parent()

	attack_timer.start(1.0) 

func _physics_process(_delta: float) -> void:
	if is_dead: return

	var is_aggressive = parent_node and parent_node.get("aggression")

	if is_aggressive and player_in_range and can_attack and can_move:
		attack()

	if not player or not is_instance_valid(player) or not can_move:
		velocity = Vector2.ZERO
		if not animP.is_playing() and can_anim:
			play_idle_animation()
		move_and_slide()
		return

	var to_player: Vector2 = player.global_position - global_position
	var direction = to_player.normalized()

	update_direction(direction)

	if is_aggressive and get_closer:
		velocity = direction * max_speed
		if can_anim:
			play_run_animation()
		move_and_slide()
	else:
		velocity = Vector2.ZERO
		if can_anim:
			play_idle_animation()

func _process(_delta):
	if hp <= 0 and not is_dead:
		death()

func update_direction(dir: Vector2):
	if abs(dir.x) > abs(dir.y):
		current_dir = Dir.LEFT if dir.x < 0 else Dir.RIGHT
	else:
		current_dir = Dir.UP if dir.y < 0 else Dir.DOWN

func play_run_animation():
	match current_dir:
		Dir.UP: anim.play("run_up")
		Dir.DOWN: anim.play("run_down")
