# Дистанции поведения
const PREFERRED_DIST = 200.0   # комфортная дистанция — держится на ней
const RETREAT_DIST   = 80.0    # ближе — отходит
const TELEPORT_INTERVAL = 8.0  # каждые N секунд телепортируется

