var player_in_slap_zone = false
var player_in_shoot_zone = false

var can_walk = true
var can_attack = true
var can_anim = true
var is_dead = false

var smite_instance: Node2D = null
var is_attacking = false

var _teleport_timer := 0.0

func _ready() -> void:
	add_to_group("enemys")
